class RescueConsoleConnection():

    def __init__(self, ip_address, port, username, password, fdsw_version="fdsw18sp", auto_discover=True, secure=True,
                 **kwargs):
        """
        Connect and authorize to FDSW Rescue Console

        .. note::
            The Rescue console needs to be reachable on provided ip address and port.
            SUPPORTED FDSW VERSIONS: fdsw18sp, fdsw18a, fdsw19, fdsw19a, fdsw20a, fdsw20b, fdsw21a, fdsw21b, fdsw21c,
            fdsw21d, fdsw21e, fdsw21f, fdsw22a, fdsw22b, fdsw23a, fdsw23b

        :param str ip_address: ie. 192.168.255.129
        :param int port: ie. 443
        :param str username: Username to authenticate to Rescue Console
        :param str password: Password to authenticate to Rescue Console
        :param str fdsw_version: Default: fdsw18sp .Specific FDSW version that you want to connect to -
                                needs to be in line with what is running on Node B
                                NOTE: To use specific version, you need to disable auto_discover by setting it to False
        :param bool auto_discover: Default: True, Enable auto-discovery of FDSW version that is running on NodeB.
                                    Auto discover will try all supported FDSW versions from latest to oldest,
                                    and connect to first compliant version.
        :param bool secure: Default: True, Enable secure connection to Node B (ie., https for http client)

        |
        :kwargs should be used to set **file_path** and **log_level** for logging:
            * **file_path** (string) - path for logs file. Default is '~/jsilib.log'
            * **log_level** (string) - log level. Default is 'INFO'
        |
        """

        _create_logger(**kwargs)

        if auto_discover is True:
            self._fdsw_interface = FdswProvider.discover_fdsw_interface(
                ip_address=ip_address,
                port=port,
                username=username,
                password=password,
                secure=secure)
        else:
            self._fdsw_interface = FdswProvider.get_fdsw_interface(
                fdsw_version=fdsw_version,
                ip_address=ip_address,
                port=port,
                username=username,
                password=password,
                secure=secure)

    def disconnect(self):
        """
        Disconnect from Rescue Console

        """
        self._fdsw_interface.disconnect()

    @staticmethod
    def setup_remote(ssh_host, ssh_port, ssh_username, ssh_password,
                     remote_host="192.168.255.129", remote_port=443, local_host="127.0.0.1", local_port=8888):
        """
        Setup SSH tunnel to remote FDSW Rescue Console

        :param str ssh_host: IP address of the remote SSH server
        :param int ssh_port: Port of the remote SSH server
        :param str ssh_username: Username to authenticate to the remote SSH server
        :param str ssh_password: Password to authenticate to the remote SSH server

        :param str remote_host: IP address of the WebSocket server on the remote machine
        :param int remote_port: Port of the WebSocket server on the remote machine
        :param str local_host: Local IP address for tunneling
        :param int local_port: Local port for tunneling

        :return: RemoteConnection instance.
        """
        remote_connection = RemoteConnection(ssh_host, ssh_port, ssh_username, ssh_password)
        remote_connection.setup_tunnel(remote_host, remote_port, local_host, local_port)
        return remote_connection

    @staticmethod
    def disconnect_remote(remote_connection):
        """
        Disconnects SSH tunnel to remote FDSW Rescue Console

        :param str remote_connection: RemoteConnection instance to close
        """
        remote_connection.close()

    @reconnect
    def get_active_sw_version_name(self, max_slot_number=3, timeout=10):
        """
        Get the Software Release Version of Software that is currently set as Active.
        NOTE: In case of fallback cases Active might not be the Currently Running software.

        :param max_slot_number: Default 3. Number of SW partitions on Node B.
        :param int timeout: Keyword execution timeout.
        :return str: Software Release Version ie. 5G18A_FSMK_0004_000008_000355
        """
        return self._fdsw_interface.swm.get_active_sw_version_name(max_slot_number=max_slot_number,
                                                                   timeout=timeout)

    @reconnect
    def get_sw_version_name(self, sw_slot_id, timeout=10):
        """
        Get the Software Release Version of Software on specified SW partition on Node B.
        NOTE: SW partition ID is HW specific ie. ASIA/ASIK 1 and 2 are SW partitions, and 3 is DNR (FDSW) for recovery.

        :param int sw_slot_id: ID of SW partition on NodeB.
        :param int timeout: Keyword execution timeout.
        :return str: Software Release Version ie. 5G18A_FSMK_0004_000008_000355
        """
        sw_inventory = self._fdsw_interface.swm.get_sw_inventory(sw_slot_id=sw_slot_id, timeout=timeout)
        sw_version = sw_inventory.sw_version
        if not sw_version:
            return None
        return sw_version

    @reconnect
    def get_running_sw_version_name(self, timeout=10):
        """
        Get the Software Release Version of currently running Software on Node B.

        :param Union[int,str] timeout: Keyword execution timeout.
        :return str: Software Release Version ie. 5G18A_FSMK_0004_000008_000355
        """
        return self._fdsw_interface.swm.get_running_sw_version_name(timeout=timeout)

    @reconnect
    def get_active_sw_partition(self, timeout=10):
        """
        Get partition id running software that is currently set as Active.

        :param Union[int,str] timeout: Keyword execution timeout.
        :return str: Active SW partition id  ie. 1
        """
        return self._fdsw_interface.swm.get_active_sw_partition(timeout=timeout)

    @reconnect
    def get_all_software_inventory(self, timeout=10):
        """
        Get all software inventory

        :param int timeout: Keyword execution timeout.
        :return dict: full software inventory details e.g.:
        {
        'slots':
            [{'id': '1', 'mode': 'Passive', 'running': False, 'status': 'Idle', 'version': '5G19B_GNB_0007_003836_000586'},
            {'id': '2', 'mode': 'Active', 'running': True, 'status': 'Idle', 'version': 'LN_WN_FDSW21D_ASIK_0000_000096_802909'}],
        'status':
        {'softwareActivation': 'Idle', 'softwareDownload': 'Successful', 'swUpdateBy': None, 'updateProgress': 1.0}
        }

        """
        software_inventory = self._fdsw_interface.swm.get_all_software_inventory(timeout=timeout).to_dict()
        software_inventory['slots'] = list(software_inventory['slots'])
        return software_inventory

    def software_update(self, sw_pkg_path, activate=False, timeout=360, **kwargs):
        """
        Uploads given software package on specified partition on Node B and activates it if param `activate` is `True`.
        In case desired SW Release is already installed on desired slot, the FDSW RC shall not over-write files, it
        will just check consistency and switch to the partition slot.

        .. note::

            SW partition ID is HW specific ie. ASIA/ASIK 1 and 2 are SW partitions, and 3 is DNR (FDSW) for recovery.

        .. note::

            When performing software update with immediate activation (activate=True) library will disconnect

        :param str sw_pkg_path: absolute or relative path to software package (zip) that will be uploaded.
                                Should contain TargetBD file. From FDSW20B None is accepted as parameter.
        :param Union[int,str] timeout: Timeout for sending request, defaults to 30
        :param bool activate: activates partition after sw upload if True, defaults to False
        **kwargs: accepted parameters as below
            :param Union[int,str] sw_slot_id: available for legacy FDSW software releases (before FDSW20B)
            Accepted parameters from FDSW23B
            :param list[str] activation_options: When activating, place one or more options from
                                                 `activationOptions` list returned by get_all_software_inventory to change
                                                 the way activation is performed.
            .. note::
                Applicable only while on DNR (recovery) partition.

        :raises ClientConnectionFailed: When client connection is lost during operation, possibly due to BTS reset.
        """

        return self._fdsw_interface.swm.software_update(sw_pkg_path=sw_pkg_path,
                                                        activate=activate, timeout=timeout, **kwargs)

    @reconnect
    def cancel_software_update(self, timeout=10):
        """
        Cancels software update.

        :param Union[int,str] timeout: Keyword execution timeout.
        """
        return self._fdsw_interface.swm.cancel_software_update(timeout=timeout)

    def software_rollback(self, sw_slot_id, timeout=10, **kwargs):
        """
        Rollbacks software

        .. note::
            After successful operation library connection is closed

        :param int sw_slot_id: ID of SW partition on Node B.
        :param Union[int,str] timeout: Keyword execution timeout.
        **kwargs: accepted parameters as below
            Accepted parameters from FDSW23B
            :param str reset_type: When activating, place one option from list returned by get_available_reset_options
                                   to change the way activation is performed.
            From FDSW23D
            :param list[str] reset_type: When activating, place one on more options from list returned by get_available_reset_options
                                   to change the way activation is performed.
            .. note::
                Applicable only while on DNR (recovery) partition.
        """
        return self._fdsw_interface.swm.software_rollback(sw_slot_id=sw_slot_id, timeout=timeout, **kwargs)

    def trigger_factory_reset(self, sw_slot_id, timeout=10):
        """
        Trigger factory reset

        The selected partition will be restored to factory settings.
        Software version will be overwritten with D&RSW.

        NOTE: Avaliable since FDSW 22B

        :param int sw_slot_id: ID of SW partition on Node B
        :param Union[int,str] timeout: Keyword execution timeout.
        """
        self._fdsw_interface.swm.trigger_factory_reset(sw_slot_id, timeout=timeout)

