    @reconnect
    def set_autoconnection(self, timeout=10, **kwargs):
        """
        Set the auto connection parameters and save.

        #Plug and Play protocol parameters, managementPlaneParameters and certificateServerParameters
        :param str primary_ip_address: gNodeB OAM IP Address from CIQ (mandatory up to FDSW21A and always in 'private network manual' scenario)
        :param int primary_prefix_length: Prefix length e.g. 112 (mandatory up to FDSW21A and always in 'private network manual' scenario)
        :param str primary_gateway: Default Gateway from CIQ (mandatory up to FDSW21A and always in 'private network manual' scenario)
        :param str scenario: name of used scenario, e.g., 'private network manual' (mandatory since FDSW21A)
        :param Union[RescueConsoleConnection,str] connection: RescueConsoleConnection object or if used, string name alias.

        **kwargs: accepted parameters as below
            Accepted parameters for FDSW19A

            :param str identification_entity_ip_address: TargetSW Mediator IP
            :param str vlan_id: primary VLAN ID
            :param str secondary_ip_address: secondary gNodeB OAM IP Address from CIQ
            :param int secondary_prefix_length: secondary Prefix length e.g. 112
            :param int secondary_vlan_id: secondary VLAN ID from CIQ
            :param str ip_address: certificate server  ip address
            :param int server_port: server port number
            :param str subject_name: name of the certificate
            :param str directory: directory name e.g. /tmp
            :param str vpn_gateway_ip_address: VPN gateway IP address (works as Serving SGW in public network scenario and is mandatory)
            :param str protocol: plug and play protocol parameters name.

            Accepted parameters for FDSW21A
            * *inner_mplane_ip_version* (``str``) management plane IP version, either  IPv4 or IPv6

            Accepted parameters for FDSW21D

            * *ethernet_port* (``str``)  ethernet port name
            * *primary_dns* (``str``) primary dns ip address
            * *secondary_dns* (``str``) secondary dns ip address

            Accepted parameters for FDSW22A

            * *san_sn_validation*
            * *san_configuration*
            * *ee_cert_subject_name*
            * *ee_subject_alt_names* (``list[str]``) ip address or domain name for SANS
            * *bts_number_of_san*
            * *san_sn_validation*
            * *ike_identity_to_use*
            * *ee_ike_identity_index*

            Accepted parameters for FDSW23B

            * *enforce_cmp_init*: Causes CMP reinitialization even if certificates are already present

            Accepted parameters for FDSW23C

            * *cmp_security_gateway_ip_address*: Initial SGW
            * *delete_operator_cert*

        :param Union[int,str] timeout: Keyword execution timeout.
        """
        return self._fdsw_interface.autoconnection.set_autoconnection(timeout, **kwargs)

    @reconnect
    def set_autoconnection_parameters_to_default(self, primary_ip_address=None,
                                                 primary_prefix_length=None, primary_gateway=None,
                                                 identification_entity_ip_address=None,
                                                 secondary_ip_address=None, secondary_prefix_length=None,
                                                 secondary_vlan_id=None, ip_address=None, server_port=None,
                                                 subject_name=None, directory=None, vpn_gateway_ip_address=None,
                                                 timeout=10, site_id=None, sec_gateway=None,
                                                 vlan_id=None, protocol=None, primary_vlan_id=None,
                                                 scenario=u'private network with DHCP'):
        """
        Restore auto connection parameters to default.

        #Plug and Play protocol parameters, managementPlaneParameters and certificateServerParameters
        :param str primary_ip_address: gNodeB OAM IP Address from CIQ
        :param int primary_prefix_length: Prefix length e.g. 112
        :param str primary_gateway: Default Gateway from CIQ
        :param str identification_entity_ip_address: TargetSW Mediator IP
        :param str secondary_ip_address: secondary gNodeB OAM IP Address from CIQ
        :param int secondary_prefix_length: secondary Prefix length e.g. 112
        :param int secondary_vlan_id: secondary VLAN ID from CIQ
        :param str ip_address: ip address
        :param int server_port: server port number
        :param str subject_name: name of the certificate
        :param str directory: directory name e.g. /tmp
        :param str vpn_gateway_ip_address: VPN gateway IP address
        :param str scenario: name of used scenario, e.g., 'private network manual' (mandatory since FDSW21A)
        :param Union[int,str] timeout: Keyword execution timeout.
        **kwargs: accepted parameters as below
            accepted parameters for FDSW18SP
            :param str site_id: Autoconnection site Id
            :param str sec_gateway: secondary gateway
            :param str vlan_id: vlan Id

            accepted parameter for FDSW18A
            :param str vlan_id: vlan Id

            accepted parameter for FDSW19
            :param str protocol: plug and play protocol parameters name.
            :param int primary_vlan_id: VLAN ID from CIQ

        :return: None
        """
        return self._fdsw_interface.autoconnection.set_autoconnection_parameters_to_default(
            primary_ip_address=primary_ip_address,
            primary_prefix_length=primary_prefix_length,
            primary_gateway=primary_gateway,
            identification_entity_ip_address=identification_entity_ip_address,
            secondary_ip_address=secondary_ip_address,
            secondary_prefix_length=secondary_prefix_length,
            secondary_vlan_id=secondary_vlan_id,
            ip_address=ip_address,
            server_port=server_port,
            subject_name=subject_name,
            directory=directory,
            vpn_gateway_ip_address=vpn_gateway_ip_address,
            timeout=timeout,
            site_id=site_id,
            sec_gateway=sec_gateway,
            vlan_id=vlan_id,
            protocol=protocol,
            primary_vlan_id=primary_vlan_id,
            scenario=scenario)

