    def download_technical_logs(self, path, timeout, log_filename=None):
        """
        Download technical logs

        :param str path: Destination dir for log file
        :param Union[int,str] timeout: Keyword execution timeout.
        :param str log_filename: Optional file name
        :return str: path to file
        """
        try:
            zip_file_path = self._get_dest_file_path(path) if log_filename is None else os.path.join(path, log_filename)
            if not zip_file_path.endswith('.zip'):
                zip_file_path += '.zip'
            self._fdsw_interface.diagnostics.download_technical_logs(zip_file_path, timeout=timeout)
            return zip_file_path
        except TimeoutExceeded:
            self._fdsw_interface.diagnostics.stop_collecting_logs(timeout=timeout)
            raise TimeoutExceeded

    def _get_dest_file_path(self, path):
        site_id_info = self.get_site_identification_info()
        site_id = site_id_info['bts_id']
        if site_id is None:
            site_id = 'NoBtsId'
        serial = site_id_info['serial_number']

        today = datetime.today()
        date = today.strftime('%a_%b_%d_%Y_%H_%M_%S')
        zip_file_name = '{}_{}_{}'.format(site_id, serial, date)
        return os.path.join(path, zip_file_name)

